    <style>
        body {font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; margin:0; background:#f9f9f9; color:#333;}
        a {text-decoration:none; color:#333;}
        header {background:#fff; border-bottom:1px solid #e0e0e0;}
        .nav {max-width:1200px; margin:auto; display:flex; align-items:center; justify-content:space-between; padding:15px;}
        .logo {font-size:24px; font-weight:bold; color:#d9534f;}
        .menu {display:flex; gap:20px;}
        .menu a {padding:5px 10px; font-size:16px;}
        .menu a:hover {color:#d9534f;}
        .hero {background:url('data:image/jpeg;base64,'); background-size:cover; background-position:center; height:400px; position:relative; color:#fff;}
        .hero::after {content:""; position:absolute; inset:0; background:rgba(0,0,0,0.4);}
        .hero-text {position:absolute; bottom:30px; left:30px; z-index:1;}
        .hero-text h1 {font-size:48px; margin:0;}
        .hero-text p {font-size:20px; margin-top:10px;}
        .section {max-width:1200px; margin:auto; padding:40px 20px;}
        .section h2 {font-size:32px; margin-bottom:20px; color:#d9534f;}
        .footer {background:#333; color:#fff; text-align:center; padding:20px; font-size:14px;}
        @media (max-width:768px){
