<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>关于我们 - 家味餐厅</title>
    <style>
        body {font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;margin:0;background:#f9f9f9;color:#333;}
        header {background:#fff;border-bottom:1px solid #e0e0e0;}
        .nav {max-width:1200px;margin:auto;display:flex;align-items:center;justify-content:space-between;padding:15px;}
        .logo {font-size:24px;font-weight:bold;color:#d9534f;}
        .menu {display:flex;gap:20px;}
        .menu a {padding:5px 10px;font-size:16px;color:#333;}
        .menu a:hover {color:#d9534f;}
        .container {max-width:1200px;margin:auto;padding:40px 20px;}
        h1 {font-size:36px;color:#d9534f;margin-bottom:20px;}
